import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import 'course_sheet.dart';
import 'course_sheet_data.dart';

class CourseSheetsListScreen extends StatefulWidget { const CourseSheetsListScreen({super.key}); @override State<CourseSheetsListScreen> createState()=>_CourseSheetsListScreenState(); }
class _CourseSheetsListScreenState extends State<CourseSheetsListScreen> { String q=''; @override Widget build(BuildContext c){ final items=preloadedCourseSheets.where((s)=>s.title.toLowerCase().contains(q.toLowerCase())).toList(); return Scaffold(backgroundColor:const Color(0xff263238),appBar:AppBar(title:Text('Fiches de cours',style:GoogleFonts.abel()),backgroundColor:const Color(0xff263238)),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(hintText:'Rechercher une fiche',prefixIcon:Icon(Icons.search)))),Expanded(child:ListView(children:items.map((s)=>Card(child:ListTile(title:Text(s.title),subtitle:Text('${s.classLevel.name} • ${s.discipline.name}'),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>CourseSheetDetailScreen(sheet:s))))).toList()))]); } }
class CourseSheetDetailScreen extends StatelessWidget { final CourseSheet sheet; const CourseSheetDetailScreen({super.key,required this.sheet}); @override Widget build(BuildContext c)=>Scaffold(backgroundColor:const Color(0xff263238),appBar:AppBar(title:Text(sheet.title,style:GoogleFonts.abel()),backgroundColor:const Color(0xff263238)),body:ListView(padding:const EdgeInsets.all(20),children:[Text(sheet.chapter,style:const TextStyle(color:Color(0xff4CAF50),fontSize:18)),const SizedBox(height:16),_section('Concepts clés',sheet.keyConcepts),_section('Formules',sheet.formulasLatex),_section('Applications pratiques',sheet.practicalApplications)]); static Widget _section(String h,String b)=>Padding(padding:const EdgeInsets.only(bottom:24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(h,style:const TextStyle(color:Color(0xff4CAF50),fontSize:20)),const SizedBox(height:8),Text(b,style:const TextStyle(color:Colors.white,fontSize:16,height:1.5))])); }
